from lib import *
L = lambda *a, **k: lesson(32, "A0", *a, **k)
V = "verb"
A = "adjective"
L(1, "Тіло", "Назвати основні частини тіла.",
 "Частини тіла вживають із my, your, his, her: my hand, her back. Foot має особливу множину: one foot — two feet. Back ви знаєте з go back; як назва частини тіла це «спина».",
 [W("body", "/ˈbɒdi/", "noun", "тіло", "The human body.", "Людське тіло."),
  W("head", "/hed/", "noun", "голова", "My head.", "Моя голова."),
  W("arm", "/ɑːm/", "noun", "рука (від плеча)", "My left arm.", "Моя ліва рука."),
  W("hand", "/hænd/", "noun", "рука (кисть)", "My right hand.", "Моя права рука."),
  W("leg", "/leɡ/", "noun", "нога (вся)", "My leg.", "Моя нога."),
  W("foot", "/fʊt/", "noun", "стопа", "My left foot.", "Моя ліва стопа."),
  W("back", "/bæk/", "noun", "спина", "My back.", "Моя спина.")],
 [li("It's my birthday today!", "Повторимо. Що відповісти?", ["Happy birthday!", "Merry Christmas!", "You're welcome!"], "Happy birthday!"),
  mt([("head", "голова"), ("arm", "рука від плеча"), ("hand", "кисть"), ("leg", "нога"), ("foot", "стопа"), ("back", "спина")], "Arm — уся рука, hand — лише кисть. Leg — уся нога, foot — стопа."),
  liu("My left hand.", "Прослухайте. Про що мова?", ["Ліва рука (кисть)", "Права рука (кисть)", "Ліва нога"], "Left hand."),
  liu("He has long legs.", "Прослухайте. Що в нього довге?", ["Ноги", "Руки", "Волосся"], "Long legs."),
  mc("Як сказати «дві стопи»?", ["two feet", "two foots", "two foot"], "Foot → feet."),
  mcu("Чим ви пишете?", ["hand", "foot", "back"], "Hand — кисть."),
  mcu("На чому носять капелюх?", ["head", "arm", "leg"], "Head — голова."),
  fb("I have two arms and two ___.", ["legs", "heads", "backs"], "Two arms and two legs."),
  fb("Put your ___ in your pockets. It's cold.", ["hands", "feet", "legs"], "У кишені ховають hands."),
  bs("У нього великі стопи.", ["He", "has", "big", "feet"], ["foot", "have"], "He has big feet."),
  tr("Моя права рука.", ["My right hand", "My right arm"], "My right hand."),
  li("Which hand do you write with?", "Ви пишете правою. Що відповісти?", ["My right hand.", "My right foot.", "My hand right the."], "My right hand.")])
L(2, "Обличчя й решта", "Назвати частини обличчя й тіла, які найчастіше болять.",
 "Tooth, як і foot, має особливу множину: one tooth — two teeth. У knee літера k не вимовляється. Stomach читається «стамек».",
 [W("nose", "/nəʊz/", "noun", "ніс", "A small nose.", "Малий ніс."),
  W("mouth", "/maʊθ/", "noun", "рот", "Open your mouth.", "Відкрийте рот."),
  W("ear", "/ɪə/", "noun", "вухо", "My left ear.", "Моє ліве вухо."),
  W("neck", "/nek/", "noun", "шия", "A long neck.", "Довга шия."),
  W("stomach", "/ˈstʌmək/", "noun", "живіт, шлунок", "My stomach.", "Мій живіт."),
  W("knee", "/niː/", "noun", "коліно", "My right knee.", "Моє праве коліно."),
  W("finger", "/ˈfɪŋɡə/", "noun", "палець (на руці)", "Ten fingers.", "Десять пальців."),
  W("tooth", "/tuːθ/", "noun", "зуб", "A white tooth.", "Білий зуб.")],
 [fb("I have two hands and two ___.", ["feet", "foots", "foot"], "Foot → feet.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("nose", "ніс"), ("mouth", "рот"), ("ear", "вухо"), ("neck", "шия")], "Частини голови."),
  mt([("stomach", "живіт"), ("knee", "коліно"), ("finger", "палець"), ("tooth", "зуб")], "Те, що часто болить."),
  liu("Open your mouth, please.", "Прослухайте. Що треба зробити?", ["Відкрити рот", "Закрити рот", "Показати зуби"], "Open your mouth."),
  liu("She has blue eyes and a small nose.", "Прослухайте. Який у неї ніс?", ["Малий", "Великий", "Довгий"], "A small nose."),
  mc("Як сказати «два зуби»?", ["two teeth", "two tooths", "two tooth"], "Tooth → teeth."),
  mcu("Чим ви слухаєте?", ["ears", "eyes", "knees"], "Ears — вуха."),
  mcu("Що на руці?", ["fingers", "knees", "teeth"], "Fingers — пальці на руці."),
  fb("I have ten ___.", ["fingers", "ears", "necks"], "Ten fingers."),
  fb("We hear with our ___.", ["ears", "eyes", "mouths"], "Hear — чути: вухами."),
  bs("Відкрийте рот, будь ласка.", ["Open", "your", "mouth", "please"], ["close", "my"], "Open your mouth, please."),
  tr("Моє праве коліно.", ["My right knee"], "My right knee.")])
L(3, "У мене болить спина", "Сказати, що саме болить.",
 "Hurt — «боліти»: My back hurts. Якщо болить кілька частин — без -s: My legs hurt. Для частих болів є готові слова з -ache: headache, stomach ache, toothache. Перед headache і stomach ache кажуть I have a…, а toothache у Британії вживають без a: I have toothache. A sore throat — біль у горлі.",
 [W("hurt", "/hɜːt/", V, "боліти", "My back hurts.", "У мене болить спина."),
  W("pain", "/peɪn/", "noun", "біль", "I have a pain in my arm.", "У мене болить рука."),
  W("stomach ache", "/ˈstʌmək eɪk/", "noun", "біль у животі", "I have a stomach ache.", "У мене болить живіт."),
  W("toothache", "/ˈtuːθeɪk/", "noun", "зубний біль", "I have toothache.", "У мене болить зуб."),
  W("sore throat", "/ˌsɔː ˈθrəʊt/", "noun", "біль у горлі", "I have a sore throat.", "У мене болить горло.")],
 [fb("We hear with our ___.", ["ears", "eyes", "teeth"], "Ears.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("hurt", "боліти"), ("pain", "біль"), ("stomach ache", "біль у животі"), ("toothache", "зубний біль"), ("sore throat", "біль у горлі")], "Head + ache = headache, tooth + ache = toothache."),
  liu("My back hurts.", "Прослухайте. Що болить?", ["Спина", "Шия", "Голова"], "My back."),
  liu("I have a sore throat and a cough.", "Прослухайте. Що з людиною?", ["Болить горло й кашель", "Болить голова й кашель", "Болить горло й живіт"], "A sore throat and a cough."),
  liu("My feet hurt.", "Прослухайте. Що болить?", ["Стопи", "Зуби", "Руки"], "My feet."),
  fb("My knee ___.", ["hurts", "hurt", "is hurt"], "Одне коліно — hurts."),
  fb("My legs ___.", ["hurt", "hurts", "hurting"], "Кілька — hurt, без -s."),
  fb("I have a stomach ___.", ["ache", "hurt", "sick"], "A stomach ache."),
  mc("Як сказати «У мене болить голова»?", ["I have a headache.", "I have head hurt.", "My head is a pain."], "I have a headache або My head hurts."),
  mc("Як сказати «У неї болить зуб»?", ["She has toothache.", "She have toothache.", "Her tooth hurt."], "She has toothache."),
  bs("У мене болить спина.", ["My", "back", "hurts"], ["hurt", "is"], "My back hurts."),
  li("What's the problem?", "У вас болить живіт. Що відповісти?", ["I have a stomach ache.", "I'm a stomach ache.", "My stomach hurt is."], "I have a stomach ache.")])
L(4, "Як ви почуваєтеся?", "Розповісти про самопочуття й спитати про нього.",
 "How do you feel? — «Як ви почуваєтеся?». Відповідь: I feel… і слово-опис: I feel sick. I feel tired. I feel better — «мені краще». I feel worse — «мені гірше». What's the matter? — «Що сталося? Що з вами?»",
 [W("feel", "/fiːl/", V, "почуватися", "I feel fine.", "Я почуваюся добре."),
  W("sick", "/sɪk/", A, "хворий; той, кого нудить", "I feel sick.", "Мене нудить."),
  W("better", "/ˈbetə/", A, "кращий, краще", "I feel better today.", "Сьогодні мені краще."),
  W("worse", "/wɜːs/", A, "гірший, гірше", "I feel worse.", "Мені гірше."),
  W("dizzy", "/ˈdɪzi/", A, "той, у кого паморочиться голова", "I feel dizzy.", "У мене паморочиться голова."),
  W("What's the matter?", "/ˌwɒts ðə ˈmætə/", "phrase", "Що сталося?", "What's the matter?", "Що сталося?")],
 [li("What's the problem?", "Повторимо. У вас болить горло. Що відповісти?", ["I have a sore throat.", "I'm sore throat.", "My throat hurt it."], "I have a sore throat."),
  mt([("feel", "почуватися"), ("sick", "хворий"), ("better", "краще"), ("worse", "гірше"), ("dizzy", "паморочиться голова")], "Better і worse — протилежні слова."),
  liu("How do you feel today?", "Прослухайте. Що вас питають?", ["Як ви сьогодні почуваєтеся", "Що ви сьогодні робите", "Де ви сьогодні"], "How do you feel?"),
  liu("I feel much better, thank you.", "Прослухайте. Як почувається людина?", ["Набагато краще", "Гірше", "Так само"], "Much better — набагато краще."),
  liu("What's the matter? You look tired.", "Прослухайте. Що помітив співрозмовник?", ["Що людина має втомлений вигляд", "Що людина весела", "Що людина запізнилася"], "You look tired — у вас утомлений вигляд."),
  fb("I ___ dizzy. Can I sit here?", ["feel", "have", "hurt"], "I feel dizzy."),
  fb("How ___ you feel?", ["do", "are", "is"], "Feel — дія: How do you feel?"),
  fb("I feel ___ today. I can go to work.", ["better", "worse", "sick"], "Можна на роботу — отже, better."),
  mc("Як правильно?", ["She feels sick.", "She feel sick.", "She is feel sick."], "З she — feels."),
  bs("Сьогодні мені краще.", ["I", "feel", "better", "today"], ["am", "worse"], "I feel better today."),
  tr("Що сталося?", ["What's the matter", "What is the matter", "What's wrong"], "What's the matter?"),
  li("What's the matter?", "У вас паморочиться голова. Що відповісти?", ["I feel dizzy.", "I'm feel dizzy.", "I have dizzy."], "I feel dizzy.")])
L(5, "Одужуйте!", "Дати просту пораду хворому й викликати допомогу.",
 "Поради дають наказовою формою: Rest — «відпочиньте». Stay in bed. Drink a lot of water. See a doctor — «зверніться до лікаря». Побажання: Get well soon! — «Одужуйте швидше!». Take care — «бережіть себе». У біді: Call an ambulance! — «Викличте швидку!»",
 [W("rest", "/rest/", V, "відпочивати, лежати", "You need to rest.", "Вам треба відпочити."),
  W("see a doctor", "/ˌsiː ə ˈdɒktə/", "phrase", "звернутися до лікаря", "See a doctor today.", "Зверніться до лікаря сьогодні."),
  W("get well soon", "/ˌɡet wel ˈsuːn/", "phrase", "одужуйте швидше", "Get well soon!", "Одужуйте швидше!"),
  W("take care", "/ˌteɪk ˈkeə/", "phrase", "бережіть себе", "Take care!", "Бережіть себе!"),
  W("ambulance", "/ˈæmbjələns/", "noun", "швидка допомога", "Call an ambulance!", "Викличте швидку!"),
  W("emergency", "/ɪˈmɜːdʒənsi/", "noun", "надзвичайна ситуація", "It's an emergency.", "Це терміново.")],
 [fb("I ___ sick. I can't go to work.", ["feel", "hurt", "rest"], "I feel sick.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("rest", "відпочивати"), ("see a doctor", "звернутися до лікаря"), ("get well soon", "одужуйте швидше"), ("take care", "бережіть себе")], "Що кажуть хворому."),
  mt([("ambulance", "швидка допомога"), ("emergency", "надзвичайна ситуація"), ("hospital", "лікарня"), ("nurse", "медсестра")], "Слова для термінових випадків."),
  liu("Stay in bed and drink a lot of water.", "Прослухайте. Що радять?", ["Лежати й багато пити", "Іти на роботу", "Викликати швидку"], "Stay in bed, drink a lot of water."),
  liu("Call an ambulance! It's an emergency!", "Прослухайте. Що треба зробити?", ["Викликати швидку", "Піти до аптеки", "Зачекати до завтра"], "Call an ambulance."),
  liu("Get well soon!", "Прослухайте. Що вам бажають?", ["Швидше одужати", "Гарного дня", "Гарної дороги"], "Get well soon."),
  fb("You have a temperature. ___ a doctor.", ["See", "Rest", "Feel"], "See a doctor."),
  fb("Call ___ ambulance!", ["an", "a", "some"], "Ambulance — з голосного: an."),
  mc("Друг захворів. Що побажати?", ["Get well soon!", "Have a nice trip!", "Happy birthday!"], "Get well soon!"),
  bs("Вам треба відпочити.", ["You", "need", "to", "rest"], ["feel", "are"], "You need to rest."),
  tr("Бережіть себе!", ["Take care"], "Take care!"),
  li("I have a cold and a headache.", "Друг каже це. Що порадити?", ["Stay in bed and rest. Get well soon!", "Go to work and rest. Get well soon!", "Call a taxi and feel."], "Stay in bed and rest. Get well soon!")])
L(6, "Повторення: тіло й самопочуття", "Сказати, що болить, як ви почуваєтеся, і дати пораду.",
 "Нових слів немає. Повторюємо: частини тіла, feet і teeth, My back hurts, I have a headache, I feel sick, better і worse, Get well soon.",
 [],
 [fb("My feet ___.", ["hurt", "hurts", "hurting"], "Feet — множина: hurt."),
  bs("У мене болить коліно.", ["My", "knee", "hurts"], ["hurt", "is"], "My knee hurts."),
  mc("Як сказати «два зуби»?", ["two teeth", "two tooths", "two teeths"], "Teeth."),
  tr("У мене болить горло.", ["I have a sore throat", "My throat hurts"], "I have a sore throat."),
  liu("I have a stomach ache and I feel dizzy.", "Прослухайте. Що з людиною?", ["Болить живіт і паморочиться голова", "Болить голова й горло", "Болить живіт і зуб"], "A stomach ache, dizzy."),
  fb("How do you ___ today? — Much better, thanks.", ["feel", "hurt", "have"], "How do you feel?"),
  mcu("Чим ви бачите?", ["eyes", "ears", "fingers"], "Eyes — очі."),
  tr("Мені гірше.", ["I feel worse"], "I feel worse."),
  liu("He can't walk. His leg hurts a lot. Call an ambulance!", "Прослухайте. Що сталося?", ["У нього сильно болить нога", "У нього болить рука", "Він утомився"], "His leg hurts a lot."),
  mc("Як правильно?", ["She has a headache.", "She has headache a.", "She is a headache."], "She has a headache."),
  li("What's the matter?", "У вас сильно болить спина. Що відповісти?", ["My back hurts a lot.", "My back hurt a lot is.", "I'm back pain."], "My back hurts a lot."),
  li("I feel sick today.", "Колега каже це. Що відповісти?", ["Go home and rest. Take care!", "Happy birthday! Take care!", "What a lovely day!"], "Go home and rest. Take care!")],
 review=True)
